<section class="cc-detail-section"><div class="cc-detail-section-header"><h5>Desglose por modelo de medición</h5></div><div class="cc-table-adaptive-wrapper cc-analytics-table-start" data-cc-table-start><table class="cc-table-adaptive"><thead><tr><th>Modelo</th><th>Ciclos</th><th>Actividad</th><th>Consumo teórico</th><th>Consumo real</th><th>Diferencia</th><th>Rendimiento teórico ponderado</th><th>Rendimiento real ponderado</th><th>Impacto económico</th></tr></thead><tbody>@foreach($desglose as $d)@php $esKm=$d->modelo_medicion===App\Models\Abastecimiento::MODELO_KILOMETROS_GALON;$unidad=$esKm?'km':($d->modelo_medicion===App\Models\Abastecimiento::MODELO_GALONES_HORA?'h':'viajes');$unidadR=$esKm?'km/gal':($d->modelo_medicion===App\Models\Abastecimiento::MODELO_GALONES_HORA?'gal/h':'gal/viaje');$teorico=$esKm?($d->consumo_teorico>0?$d->actividad/$d->consumo_teorico:null):($d->actividad>0?$d->consumo_teorico/$d->actividad:null);$real=$esKm?($d->consumo_real>0?$d->actividad/$d->consumo_real:null):($d->actividad>0?$d->consumo_real/$d->actividad:null); @endphp<tr data-model-breakdown="{{ $d->modelo_medicion }}"><td>{{ $modelos[$d->modelo_medicion] }}</td><td>{{ $d->ciclos }}</td><td class="text-right">{{ $unidad==='viajes'?number_format($d->actividad,0):number_format($d->actividad,2) }} {{ $unidad }}</td><td class="text-right">{{ number_format($d->consumo_teorico,2) }} gal</td><td class="text-right">{{ number_format($d->consumo_real,2) }} gal</td><td class="text-right">{{ number_format(abs($d->consumo_teorico-$d->consumo_real),2) }} gal</td><td class="text-right">{{ $teorico===null?'—':number_format($teorico,2).' '.$unidadR }}</td><td class="text-right">{{ $real===null?'—':number_format($real,2).' '.$unidadR }}</td><td class="text-right">{{ $dinero($d->impacto_neto) }}</td></tr>@endforeach</tbody></table></div></section>
